{"file_path":"src/election.js","content":"/**
 * Parsing and counting for the instant-runoff election.
 */

export class ElectionError extends Error {}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

function fail (message) {
  throw new ElectionError(message)
}

/** Compare two names by code point. */
export function compareNames (a, b) {
  if (a === b) return 0
  const ac = [...a]
  const bc = [...b]
  const n = Math.min(ac.length, bc.length)
  for (let i = 0; i < n; i++) {
    const x = ac[i].codePointAt(0)
    const y = bc[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return ac.length === bc.length ? 0 : (ac.length < bc.length ? -1 : 1)
}

/**
 * Parse the election text into { candidates, ballots }.
 */
export function parse (text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  let declared = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const parts = line.split(/\s+/)
    const directive = parts[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      const names = parts.slice(1)
      if (names.length === 0) {
        fail(`error: line ${n}: expected candidates <name>...`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(`error: line ${n}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          fail(`error: line ${n}: candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      declared = seen
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 3) {
        fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      }
      const countText = parts[1]
      if (!COUNT_RE.test(countText)) {
        fail(`error: line ${n}: count must be a positive integer`)
      }
      const count = Number(countText)
      const names = parts.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!declared.has(name)) {
          fail(`error: line ${n}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(`error: line ${n}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`error: line ${n}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('error: no candidates')

  return { candidates, ballots }
}

/**
 * Run the count. Returns { rounds, winner } where each round holds the vote
 * counts of the candidates continuing into it, the exhausted total and the
 * candidate eliminated at its end (if any).
 */
export function count ({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map(name => [name, []]))
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) votes.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      let target = null
      for (const name of ballot.names) {
        if (continuing.has(name)) { target = name; break }
      }
      if (target === null) exhausted += ballot.count
      else votes.set(target, votes.get(target) + ballot.count)
    }

    let active = 0
    for (const value of votes.values()) active += value
    for (const [name, value] of votes) history.get(name).push(value)

    const round = { votes, exhausted, eliminated: null }
    rounds.push(round)

    if (active === 0) break

    let majority = null
    for (const [name, value] of votes) {
      if (value * 2 > active) { majority = name; break }
    }
    if (majority !== null) { winner = majority; break }

    const eliminated = chooseEliminated(votes, history)
    continuing.delete(eliminated)
    round.eliminated = eliminated
  }

  return { rounds, winner }
}

function chooseEliminated (votes, history) {
  let least = Infinity
  for (const value of votes.values()) least = Math.min(least, value)
  let tied = []
  for (const [name, value] of votes) if (value === least) tied.push(name)
  if (tied.length === 1) return tied[0]

  const depth = history.get(tied[0]).length
  for (let r = 0; r < depth; r++) {
    let low = Infinity
    for (const name of tied) low = Math.min(low, history.get(name)[r])
    const kept = tied.filter(name => history.get(name)[r] === low)
    if (kept.length === 1) return kept[0]
    tied = kept
  }

  tied.sort(compareNames)
  return tied[tied.length - 1]
}

/** Render the result for the given mode. */
export function render (mode, { rounds, winner }) {
  let out = ''
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const entries = [...round.votes.entries()].sort((a, b) => {
        if (a[1] !== b[1]) return b[1] - a[1]
        return compareNames(a[0], b[0])
      })
      const parts = entries.map(([name, value]) => `${name}=${value}`)
      parts.push(`exhausted=${round.exhausted}`)
      out += `round ${index + 1}: ${parts.join(' ')}\n`
      if (round.eliminated !== null) out += `eliminated ${round.eliminated}\n`
    })
  } else {
    out += `rounds ${rounds.length}\n`
  }
  out += winner === null ? 'no winner\n' : `winner ${winner}\n`
  return out
}
"}

