/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'fs'

// Parse a URI reference into its components
function parseURI(uri) {
  const result = {
    scheme: undefined,
    authority: undefined,
    path: '',
    query: undefined,
    fragment: undefined,
  }

  let remaining = uri
  let idx = 0

  // Parse scheme: optional, stops at first : not preceded by /, ?, or #
  const schemeMatch = remaining.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/)
  if (schemeMatch) {
    result.scheme = schemeMatch[1]
    remaining = remaining.slice(schemeMatch[0].length)
  }

  // Parse authority: optional, introduced by // and runs to /, ?, or #
  if (remaining.startsWith('//')) {
    remaining = remaining.slice(2)
    const authorityMatch = remaining.match(/^([^/?#]*)/)
    result.authority = authorityMatch[1]
    remaining = remaining.slice(result.authority.length)
  }

  // Parse query: from ? to #
  const queryMatch = remaining.match(/^([^#]*)(?:#(.*))?$/)
  if (queryMatch) {
    const beforeFragment = queryMatch[1]
    const fragment = queryMatch[2]

    const queryIdx = beforeFragment.indexOf('?')
    if (queryIdx !== -1) {
      result.path = beforeFragment.slice(0, queryIdx)
      result.query = beforeFragment.slice(queryIdx + 1)
    } else {
      result.path = beforeFragment
    }

    if (fragment !== undefined) {
      result.fragment = fragment
    }
  }

  return result
}

// Parse authority into userinfo, host, port
function parseAuthority(authority) {
  const result = {
    userinfo: undefined,
    host: '',
    port: undefined,
  }

  if (!authority) return result

  // Split userinfo from host:port
  const lastAtIdx = authority.lastIndexOf('@')
  let hostport = authority
  if (lastAtIdx !== -1) {
    result.userinfo = authority.slice(0, lastAtIdx)
    hostport = authority.slice(lastAtIdx + 1)
  }

  // Parse host and port
  if (hostport.startsWith('[')) {
    // IPv6 address
    const closeBracketIdx = hostport.indexOf(']')
    if (closeBracketIdx !== -1) {
      result.host = hostport.slice(1, closeBracketIdx)
      const afterBracket = hostport.slice(closeBracketIdx + 1)
      if (afterBracket.startsWith(':')) {
        result.port = afterBracket.slice(1)
      }
    }
  } else {
    // IPv4 or domain
    const colonIdx = hostport.indexOf(':')
    if (colonIdx !== -1) {
      result.host = hostport.slice(0, colonIdx)
      result.port = hostport.slice(colonIdx + 1)
    } else {
      result.host = hostport
    }
  }

  return result
}

// Reconstruct authority from parts
function reconstructAuthority(userinfo, host, port) {
  let authority = host
  if (port !== undefined) {
    authority += ':' + port
  }
  if (userinfo !== undefined) {
    authority = userinfo + '@' + authority
  }
  return authority
}

// Reconstruct URI from parts
function reconstructURI(scheme, authority, path, query, fragment) {
  let result = ''
  if (scheme !== undefined) {
    result += scheme + ':'
  }
  if (authority !== undefined) {
    result += '//' + authority
  }
  result += path
  if (query !== undefined) {
    result += '?' + query
  }
  if (fragment !== undefined) {
    result += '#' + fragment
  }
  return result
}

// Check if a character is unreserved
function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

// Check if a character is a hex digit
function isHexDigit(ch) {
  return /^[0-9A-Fa-f]$/.test(ch)
}

// Normalize percent-encodings in a component
function normalizePercentEncodings(component, componentName, lineNum) {
  if (!component) return component

  let result = ''
  let i = 0
  while (i < component.length) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const hex1 = component[i + 1]
      const hex2 = component[i + 2]
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const upperHex = '%' + hex1.toUpperCase() + hex2.toUpperCase()
      const charCode = parseInt(hex1 + hex2, 16)
      const char = String.fromCharCode(charCode)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += upperHex
      }
      i += 3
    } else {
      result += component[i]
      i++
    }
  }
  return result
}

// Remove dot segments from path per RFC 3986 section 5.2.4
function removeDotSegments(path) {
  const input = path
  const output = []
  let i = 0

  while (i < input.length) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (input.startsWith('../', i)) {
      i += 3
    } else if (input.startsWith('./', i)) {
      i += 2
    }
    // B: If the input buffer begins with a prefix of "/./"
    else if (input.startsWith('/./')) {
      i += 2
    } else if (input === '/.') {
      i = input.length - 1
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (input.startsWith('/../', i)) {
      i += 3
      if (output.length > 0) {
        output.pop()
      }
    } else if (input === '/..') {
      i = input.length - 2
      if (output.length > 0) {
        output.pop()
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if (input === '.' || input === '..') {
      i = input.length
    }
    // E: Move the first path segment to output buffer
    else {
      let segmentEnd = i
      if (input[i] === '/') {
        segmentEnd++
      }
      while (segmentEnd < input.length && input[segmentEnd] !== '/') {
        segmentEnd++
      }
      output.push(input.slice(i, segmentEnd))
      i = segmentEnd
    }
  }

  return output.join('')
}

// Normalize a URI
function normalizeURI(uri, lineNum) {
  const parsed = parseURI(uri)

  // Normalize scheme: lowercase
  if (parsed.scheme !== undefined) {
    parsed.scheme = parsed.scheme.toLowerCase()
  }

  // Normalize percent-encodings: userinfo, host, path, query, fragment (in that order)
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)

    if (auth.userinfo !== undefined) {
      auth.userinfo = normalizePercentEncodings(auth.userinfo, 'userinfo', lineNum)
    }

    if (auth.host !== undefined) {
      auth.host = normalizePercentEncodings(auth.host, 'host', lineNum)
    }

    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Normalize percent-encodings in path
  parsed.path = normalizePercentEncodings(parsed.path, 'path', lineNum)

  if (parsed.query !== undefined) {
    parsed.query = normalizePercentEncodings(parsed.query, 'query', lineNum)
  }

  if (parsed.fragment !== undefined) {
    parsed.fragment = normalizePercentEncodings(parsed.fragment, 'fragment', lineNum)
  }

  // Lowercase host
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)
    auth.host = auth.host.toLowerCase()
    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Drop default ports
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)
    if (auth.port !== undefined) {
      const defaultPorts = {
        'http': '80',
        'ws': '80',
        'https': '443',
        'wss': '443',
        'ftp': '21',
      }
      if (parsed.scheme && defaultPorts[parsed.scheme] === auth.port) {
        auth.port = undefined
      }
    }
    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Remove dot segments from path
  parsed.path = removeDotSegments(parsed.path)

  // Add / to path when authority present and path empty
  if (parsed.authority !== undefined && parsed.path === '') {
    parsed.path = '/'
  }

  return reconstructURI(parsed.scheme, parsed.authority, parsed.path, parsed.query, parsed.fragment)
}

// Merge paths per RFC 3986 section 5.2.3
function mergePaths(basePath, baseAuthority, refPath) {
  if (baseAuthority !== undefined && basePath === '') {
    return '/' + refPath
  } else {
    const lastSlashIdx = basePath.lastIndexOf('/')
    if (lastSlashIdx !== -1) {
      return basePath.slice(0, lastSlashIdx + 1) + refPath
    } else {
      return refPath
    }
  }
}

// Resolve a reference against a base
function resolve(base, reference, lineNum) {
  const baseURI = parseURI(base)
  const refURI = parseURI(reference)

  let targetScheme = baseURI.scheme
  let targetAuthority = baseURI.authority
  let targetPath = baseURI.path
  let targetQuery = baseURI.query

  if (refURI.scheme !== undefined) {
    // Reference has a scheme: use it as-is
    targetScheme = refURI.scheme
    targetAuthority = refURI.authority
    targetPath = removeDotSegments(refURI.path)
    targetQuery = refURI.query
  } else {
    if (refURI.authority !== undefined) {
      // Reference has authority: use it
      targetAuthority = refURI.authority
      targetPath = removeDotSegments(refURI.path)
      targetQuery = refURI.query
    } else {
      if (refURI.path === '') {
        // Reference has empty path
        if (refURI.query !== undefined) {
          targetQuery = refURI.query
        }
      } else {
        if (refURI.path.startsWith('/')) {
          // Reference has absolute path
          targetPath = removeDotSegments(refURI.path)
        } else {
          // Reference has relative path: merge it
          targetPath = mergePaths(baseURI.path, baseURI.authority, refURI.path)
          targetPath = removeDotSegments(targetPath)
        }
        targetQuery = refURI.query
      }
    }
  }

  const targetFragment = refURI.fragment
  const target = reconstructURI(targetScheme, targetAuthority, targetPath, targetQuery, targetFragment)

  // Normalize the result
  return normalizeURI(target, lineNum)
}

// Main logic
const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
const stdin = readFileSync(0, 'utf8')
const lines = stdin.split('\n')

// Drop the empty tail a trailing newline leaves
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

for (let i = 0; i < lines.length; i++) {
  const lineNum = i + 1
  const line = lines[i]

  if (mode === 'normalize') {
    const result = normalizeURI(line, lineNum)
    console.log(result)
  } else {
    // resolve mode
    const spaceIdx = line.indexOf(' ')
    if (spaceIdx === -1) {
      process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
      process.exit(2)
    }

    const base = line.slice(0, spaceIdx)
    const reference = line.slice(spaceIdx + 1)

    // Check that base has a scheme
    const baseParsed = parseURI(base)
    if (baseParsed.scheme === undefined) {
      process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
      process.exit(2)
    }

    const result = resolve(base, reference, lineNum)
    console.log(result)
  }
}

process.exit(0)
