 * RFC 3986 URI reference parsing, normalization and reference resolution.
 *
 * Every function here is pure: failures are reported by throwing a UriError
 * carrying the name of the component that holds the offending text.
 */

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/**
 * Split a URI reference into scheme, authority, path, query and fragment.
 * An absent component is undefined; an empty one is the empty string.
 */
export function parseUri(uri) {
  let rest = uri
  let scheme

  // The scheme runs to the first ':', which no '/', '?' or '#' may precede.
  const colon = rest.indexOf(':')
  if (colon > 0) {
    const head = rest.slice(0, colon)
    if (!/[/?#]/.test(head)) {
      scheme = head
      rest = rest.slice(colon + 1)
    }
  }

  // An authority is introduced by '//' and runs to the next '/', '?' or '#'.
  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = firstIndexOf(rest, '/?#')
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  // The fragment is everything after the first '#'.
  let fragment
  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  // The query is everything after the first remaining '?'.
  let query
  const question = rest.indexOf('?')
  if (question !== -1) {
    query = rest.slice(question + 1)
    rest = rest.slice(0, question)
  }

  return { scheme, authority, path: rest, query, fragment }
}

function firstIndexOf(text, chars) {
  for (let i = 0; i < text.length; i++) {
    if (chars.includes(text[i])) return i
  }
  return text.length
}

/** Split an authority into userinfo, host and port. */
export function parseAuthority(authority) {
  let rest = authority
  let userinfo

  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }

  // The port follows the first ':' that comes after the last ']'.
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket === -1 ? 0 : bracket + 1)
  if (colon !== -1) {
    return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
  }
  return { userinfo, host: rest, port: undefined }
}

export function formatAuthority({ userinfo, host, port }) {
  let out = userinfo === undefined ? '' : userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

export function formatUri({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

const HEX = /^[0-9A-Fa-f]$/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercase the hex digits of every '%XX' and decode the unreserved ones.
 * Throws a UriError naming `component` on a truncated escape.
 */
export function normalizePercentEncodings(text, component) {
  if (!text.includes('%')) return text
  let out = ''
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '%') {
      out += text[i]
      continue
    }
    const high = text[i + 1]
    const low = text[i + 2]
    if (high === undefined || low === undefined || !HEX.test(high) || !HEX.test(low)) {
      throw new UriError(component)
    }
    const decoded = String.fromCharCode(parseInt(high + low, 16))
    out += UNRESERVED.test(decoded) ? decoded : '%' + high.toUpperCase() + low.toUpperCase()
    i += 2
  }
  return out
}

/** Remove dot segments from a path, per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = dropLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = dropLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input[0] === '/' ? 1 : 0
      while (end < input.length && input[end] !== '/') end++
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }

  return output
}

function dropLastSegment(output) {
  const slash = output.lastIndexOf('/')
  return slash === -1 ? '' : output.slice(0, slash)
}

/** Normalize the parsed components of a URI reference in place, returning them. */
export function normalizeParts(parts) {
  const result = { ...parts }

  if (result.scheme !== undefined) result.scheme = asciiLower(result.scheme)

  if (result.authority !== undefined) {
    const auth = parseAuthority(result.authority)

    if (auth.userinfo !== undefined) {
      auth.userinfo = normalizePercentEncodings(auth.userinfo, 'userinfo')
    }
    auth.host = normalizePercentEncodings(auth.host, 'host')
    auth.host = asciiLower(auth.host)

    if (auth.port === '' || (auth.port !== undefined && DEFAULT_PORTS[result.scheme] === auth.port)) {
      auth.port = undefined
    }

    result.authority = formatAuthority(auth)
  }

  result.path = normalizePercentEncodings(result.path, 'path')
  if (result.query !== undefined) {
    result.query = normalizePercentEncodings(result.query, 'query')
  }
  if (result.fragment !== undefined) {
    result.fragment = normalizePercentEncodings(result.fragment, 'fragment')
  }

  result.path = removeDotSegments(result.path)
  if (result.authority !== undefined && result.path === '') result.path = '/'

  return result
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/** Normalize a whole URI reference. */
export function normalize(uri) {
  return formatUri(normalizeParts(parseUri(uri)))
}

/** Merge a relative reference path onto a base path, per section 5.2.3. */
export function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const slash = base.path.lastIndexOf('/')
  return slash === -1 ? refPath : base.path.slice(0, slash + 1) + refPath
}

/** Resolve a reference against a base, strictly, then normalize the target. */
export function resolve(baseUri, referenceUri) {
  const base = parseUri(baseUri)
  const ref = parseUri(referenceUri)
  const target = { path: '' }

  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    if (ref.authority !== undefined) {
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      target.authority = base.authority
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query === undefined ? base.query : ref.query
      } else {
        target.path = ref.path.startsWith('/')
          ? removeDotSegments(ref.path)
          : removeDotSegments(mergePaths(base, ref.path))
        target.query = ref.query
      }
    }
  }
  target.fragment = ref.fragment

  return formatUri(normalizeParts(target))
}
