{"file_path":"src/diff3.js","content":"/**
 * Three-way merge over whole lines.
 */

/**
 * Longest common subsequence between two arrays of lines, returned as the list
 * of matched index pairs. Ties are broken towards the earliest matches: walking
 * from the start, a match is taken whenever the current lines are equal, and
 * otherwise the side whose remaining subsequence is at least as long advances,
 * the base being preferred when the two are equal.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // suffix[i][j] = length of the LCS of base[i..] and side[j..]
  const suffix = new Array(n + 1)
  for (let i = 0; i <= n; i++) suffix[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = suffix[i]
    const next = suffix[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (suffix[i + 1][j] >= suffix[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines replaced
 * by a run of the side's lines.
 */
export function changes(base, side) {
  const matches = lcsMatches(base, side)
  const result = []
  let bi = 0
  let si = 0
  const emit = (baseEnd, sideEnd) => {
    if (baseEnd > bi || sideEnd > si) {
      result.push({ baseStart: bi, baseEnd, sideStart: si, sideEnd })
    }
  }
  for (const [mb, ms] of matches) {
    emit(mb, ms)
    bi = mb + 1
    si = ms + 1
  }
  emit(base.length, side.length)
  return result
}

/**
 * The regions of a three-way merge, in base order. Each region is either
 * `{ kind: 'stable', lines }` or a changed region carrying the three candidate
 * line runs and its resolution.
 */
export function merge(mine, base, theirs) {
  const all = []
  for (const c of changes(base, mine)) all.push({ ...c, side: 'mine' })
  for (const c of changes(base, theirs)) all.push({ ...c, side: 'theirs' })
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let pos = 0
  let k = 0
  const stable = (from, to) => {
    if (to > from) regions.push({ kind: 'stable', lines: base.slice(from, to) })
  }

  while (k < all.length) {
    const first = all[k]
    const start = first.baseStart
    let end = first.baseEnd
    const group = [first]
    k++
    while (k < all.length && all[k].baseStart <= end) {
      const next = all[k]
      if (next.baseEnd > end) end = next.baseEnd
      group.push(next)
      k++
    }

    stable(pos, start)
    pos = end

    const baseLines = base.slice(start, end)
    const sideLines = (name, doc) => {
      const own = group.filter(c => c.side === name)
      if (own.length === 0) return baseLines.slice()
      let minBase = Infinity
      let maxBase = -Infinity
      let minSide = Infinity
      let maxSide = -Infinity
      for (const c of own) {
        if (c.baseStart < minBase) minBase = c.baseStart
        if (c.baseEnd > maxBase) maxBase = c.baseEnd
        if (c.sideStart < minSide) minSide = c.sideStart
        if (c.sideEnd > maxSide) maxSide = c.sideEnd
      }
      return doc.slice(minSide - (minBase - start), maxSide + (end - maxBase))
    }

    const mineLines = sideLines('mine', mine)
    const theirsLines = sideLines('theirs', theirs)
    const mineTouched = group.some(c => c.side === 'mine')
    const theirsTouched = group.some(c => c.side === 'theirs')

    let resolution
    if (group.length === 1) {
      resolution = mineTouched ? 'mine' : 'theirs'
    } else if (same(mineLines, theirsLines)) {
      resolution = mineTouched && theirsTouched ? 'both' : mineTouched ? 'mine' : 'theirs'
    } else if (same(mineLines, baseLines)) {
      resolution = 'theirs'
    } else if (same(theirsLines, baseLines)) {
      resolution = 'mine'
    } else {
      resolution = 'conflict'
    }

    regions.push({ kind: 'changed', resolution, mine: mineLines, base: baseLines, theirs: theirsLines })
  }

  stable(pos, base.length)
  return regions
}

function same(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/** The merged document, with conflicts marked. `withBase` picks diff3 style. */
export function render(regions, withBase) {
  const out = []
  for (const region of regions) {
    if (region.kind === 'stable') {
      out.push(...region.lines)
      continue
    }
    if (region.resolution === 'conflict') {
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else if (region.resolution === 'theirs') {
      out.push(...region.theirs)
    } else {
      out.push(...region.mine)
    }
  }
  return out
}

/** One descriptive line per region. */
export function describe(regions) {
  return regions.map(region => {
    if (region.kind === 'stable') return `stable ${region.lines.length}`
    switch (region.resolution) {
      case 'conflict':
        return `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`
      case 'theirs':
        return `theirs ${region.theirs.length}`
      case 'both':
        return `both ${region.mine.length}`
      default:
        return `mine ${region.mine.length}`
    }
  })
}

export function hasConflict(regions) {
  return regions.some(region => region.kind === 'changed' && region.resolution === 'conflict')
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync, writeSync } from 'node:fs'
import { merge, render, describe, hasConflict } from './diff3.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  writeSync(2, `error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || !MODES.includes(mode)) {
  fail('usage: cli.js merge|merge2|regions')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const parts = [[]]
for (const line of lines) {
  if (line === '%%%') parts.push([])
  else parts[parts.length - 1].push(line)
}

if (parts.length !== 3) fail('expected three parts separated by %%%')

const [mine, base, theirs] = parts
const regions = merge(mine, base, theirs)
const out = mode === 'regions' ? describe(regions) : render(regions, mode === 'merge')

if (out.length > 0) writeSync(1, out.map(line => `${line}\n`).join(''))
process.exit(hasConflict(regions) ? 1 : 0)
"}

