 * The limiter file parser. It turns the text of a limiter file into the
 * declared policies, the routes and the event log, and reports the first
 * failure it meets as a ParseError carrying its line number and reason.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const TOKEN = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function isToken(word) {
  return TOKEN.test(word)
}

function integer(word, field, least, line) {
  if (!UINT.test(word)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(word)
  if (value < least) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return value
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const prefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const line = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket') {
      if (seenEvent) throw new ParseError(line, 'declarations must come before the first event')
      if (words.length !== 5) {
        throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = words[1]
      if (!isToken(name)) throw new ParseError(line, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      const capacity = integer(words[2], 'capacity', 1n, line)
      const refill = integer(words[3], 'refill', 0n, line)
      const per = integer(words[4], 'per', 1n, line)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (seenEvent) throw new ParseError(line, 'declarations must come before the first event')
      if (words.length !== 4) {
        throw new ParseError(line, 'expected window <name> <limit> <span>')
      }
      const name = words[1]
      if (!isToken(name)) throw new ParseError(line, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      const limit = integer(words[2], 'limit', 0n, line)
      const span = integer(words[3], 'span', 1n, line)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (seenEvent) throw new ParseError(line, 'declarations must come before the first event')
      if (words.length < 3) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isToken(prefix)) throw new ParseError(line, `invalid route prefix ${prefix}`)
      if (prefixes.has(prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      const chosen = []
      for (const name of words.slice(2)) {
        const policy = policies.get(name)
        if (policy === undefined) throw new ParseError(line, `unknown policy ${name}`)
        chosen.push(policy)
      }
      prefixes.add(prefix)
      routes.push({ prefix, policies: chosen })
    } else if (directive === 'event') {
      seenEvent = true
      if (words.length !== 3) throw new ParseError(line, 'expected event <tick> <key>')
      const tick = integer(words[1], 'tick', 0n, line)
      const key = words[2]
      if (!isToken(key)) throw new ParseError(line, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key })
    } else {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
  }

  return { routes, events }
}
