 * A lexical scanner for the small language.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Token {
  constructor(line, column, kind, body) {
    this.line = line
    this.column = column
    this.kind = kind
    this.body = body
  }
}

export class Scanner {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  error(reason) {
    throw new ScanError(this.line, this.column, reason)
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    return idx < this.input.length ? this.input[idx] : null
  }

  advance() {
    if (this.pos >= this.input.length) return null

    const char = this.input[this.pos]
    this.pos++

    if (char === '\n') {
      this.line++
      this.column = 1
    } else if (char === '\t') {
      // Move to next multiple of 4 + 1
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }

    return char
  }

  skipWhitespace() {
    while (this.peek() !== null) {
      const char = this.peek()
      if (char === ' ' || char === '\t' || char === '\r' || char === '\n') {
        this.advance()
      } else {
        break
      }
    }
  }

  scanLineComment() {
