{"file_path":"src/graph.js","content":"/**
 * Build and analyze the task dependency graph.
 */

export class Graph {
  constructor(tasks, deps) {
    this.tasks = tasks // Map<name, cost>
    this.deps = deps   // Map<name, Set<dependency names>>
    this.taskNames = Array.from(tasks.keys()).sort()
    this.computeDepths()
  }

  /**
   * Compute the depth (wave) of each task using DFS.
   * Depth is the maximum depth of all dependencies + 1.
   * Tasks with no dependencies have depth 0.
   */
  computeDepths() {
    this.depths = new Map()
    this.visited = new Set()
    this.visiting = new Set()

    for (const name of this.taskNames) {
      if (!this.visited.has(name)) {
        this.dfsDepth(name)
      }
    }
  }

  dfsDepth(name) {
    if (this.visited.has(name)) {
      return this.depths.get(name)
    }

    if (this.visiting.has(name)) {
      // Cycle detected during depth computation
      return -1
    }

    this.visiting.add(name)

    const dependencies = this.deps.get(name) || new Set()
    let maxDepDepth = -1

    for (const dep of dependencies) {
      const depDepth = this.dfsDepth(dep)
      if (depDepth === -1) {
        // Cycle
        this.visiting.delete(name)
        return -1
      }
      maxDepDepth = Math.max(maxDepDepth, depDepth)
    }

    this.visiting.delete(name)
    const depth = maxDepDepth + 1
    this.depths.set(name, depth)
    this.visited.add(name)
    return depth
  }

  /**
   * Detect a cycle in the graph using DFS.
   * Returns the cycle as an array of names, or null if no cycle.
   */
  detectCycle() {
    this.visited = new Set()
    this.stack = []

    for (const name of this.taskNames) {
      if (!this.visited.has(name)) {
        const cycle = this.dfsCycle(name, new Set())
        if (cycle) {
          return cycle
        }
      }
    }

    return null
  }

  dfsCycle(name, visiting) {
    if (visiting.has(name)) {
      // Found a cycle - build it from the stack
      const cycle = []
      let foundStart = false
      for (const node of this.stack) {
        if (node === name) {
          foundStart = true
        }
        if (foundStart) {
          cycle.push(node)
        }
      }
      cycle.push(name) // Close the cycle
      return cycle
    }

    if (this.visited.has(name)) {
      return null
    }

    visiting.add(name)
    this.stack.push(name)

    const dependencies = this.deps.get(name) || new Set()
    const sortedDeps = Array.from(dependencies).sort()

    for (const dep of sortedDeps) {
      const cycle = this.dfsCycle(dep, visiting)
      if (cycle) {
        return cycle
      }
    }

    this.stack.pop()
    visiting.delete(name)
    this.visited.add(name)
    return null
  }

  /**
   * Get the depth (wave) of a task.
   */
  getDepth(name) {
    return this.depths.get(name) || 0
  }

  /**
   * Get the start time of a task (max finish of all dependencies, or 0).
   */
  getStart(name) {
    const dependencies = this.deps.get(name) || new Set()
    if (dependencies.size === 0) {
      return 0
    }

    let maxFinish = 0
    for (const dep of dependencies) {
      const depFinish = this.getStart(dep) + (this.tasks.get(dep) || 0)
      maxFinish = Math.max(maxFinish, depFinish)
    }
    return maxFinish
  }

  /**
   * Get the finish time of a task (start + cost).
   */
  getFinish(name) {
    return this.getStart(name) + (this.tasks.get(name) || 0)
  }

  /**
   * Calculate the priority (longest chain from this task).
   */
  getPriority(name) {
    const memo = new Map()
    return this.calcPriority(name, memo)
  }

  calcPriority(name, memo) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    const cost = this.tasks.get(name) || 0
    let maxDepPriority = 0

    // Find tasks that depend on this one
    for (const [taskName, deps] of this.deps) {
      if (deps.has(name)) {
        const depPriority = this.calcPriority(taskName, memo)
        maxDepPriority = Math.max(maxDepPriority, depPriority)
      }
    }

    const priority = cost + maxDepPriority
    memo.set(name, priority)
    return priority
  }

  /**
   * Get all tasks.
   */
  getAllTasks() {
    return this.taskNames
  }

  /**
   * Get cost of a task.
   */
  getCost(name) {
    return this.tasks.get(name) || 0
  }

  /**
   * Get dependencies of a task.
   */
  getDependencies(name) {
    return this.deps.get(name) || new Set()
  }
}
"}

