        for (let j = 1; j < currentReady.length; j++) {
          const priorityJ = graph.getPriority(currentReady[j])
          if (priorityJ > priority0 || (priorityJ === priority0 && currentReady[j] < currentReady[bestIdx])) {
            bestIdx = j
          }
        }

        const bestTask = currentReady[bestIdx]

        // Calculate when this task can actually start:
        // - Worker must be free (workers[i].freeAt)
        // - All dependencies must be finished
        let maxDepFinish = 0
        const deps = graph.getDependencies(bestTask)
        for (const dep of deps) {
          const depFinish = finishes.get(dep) || 0
          maxDepFinish = Math.max(maxDepFinish, depFinish)
        }
        const startTime = Math.max(workers[i].freeAt, maxDepFinish)
        const cost = graph.getCost(bestTask)
        const finishTime = startTime + cost

        finishes.set(bestTask, finishTime)
        workers[i].freeAt = finishTime
        workers[i].tasks.push({
          name: bestTask,
          start: startTime,
          finish: finishTime
        })

        scheduled.add(bestTask)
        currentReady.splice(bestIdx, 1)
        anyAssigned = true
      }
    }

    processedTimes.add(currentTime)
  }"}

