function parseSheet(lines) {
  const cells = new Map() // address -> { content, isFormula }

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum]

    // Strip leading spaces and tabs
    line = line.replace(/^[ \t]+/, '')

    // Skip empty lines and comments
    if (!line || line[0] === '#') continue

    // Extract token up to space/tab or end of line
    const tokenMatch = line.match(/^(\S+)/)
    if (!tokenMatch) continue

    const token = tokenMatch[1]

    // Check if it looks like an address (letters + digits)
    const addressLikeMatch = token.match(/^([A-Za-z]+)(\d+)$/)
    if (!addressLikeMatch) continue // Not address-like, skip

    const rawAddress = token
    const address = rawAddress.toUpperCase()

    // Validate address
    if (!isValidAddress(address)) {
      throw new Error(`error: line ${lineNum + 1}: invalid cell address ${rawAddress}`)
    }

    // Get the rest after token
    let rest = line.slice(token.length)

    // Skip one run of spaces and tabs
    rest = rest.replace(/^[ \t]+/, '')

    const content = rest

    // Check for duplicate
    if (cells.has(address)) {
      throw new Error(`error: line ${lineNum + 1}: cell ${address} is declared twice`)
    }

    const isFormula = content.startsWith('=')
    cells.set(address, {
      content: isFormula ? content.slice(1) : content,
      isFormula
    })
  }

  return cells
}"}

