{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseArgs } from './args.js'
import { parseInput } from './parse.js'
import { findCycle, computeDepths, computeTimings, computePriorities, byName } from './graph.js'
import { renderWaves, renderExplain, renderPack } from './render.js'

function fail(message, code) {
  process.stderr.write(message + '\n')
  process.exitCode = code
}

async function readStdin() {
  let input = ''
  process.stdin.setEncoding('utf8')
  for await (const chunk of process.stdin) input += chunk
  return input
}

async function main() {
  const argv = process.argv.slice(2)

  const args = parseArgs(argv)
  if (args.error) return fail(args.error, 2)

  const input = await readStdin()

  const parsed = parseInput(input)
  if (parsed.error) return fail(parsed.error, 2)

  const { tasks, dependencies } = parsed

  const cycle = findCycle(tasks, dependencies)
  if (cycle) return fail('error: cycle: ' + cycle.join(' -> '), 3)

  if (args.command === 'waves') {
    const depths = computeDepths(tasks, dependencies)
    const timings = computeTimings(tasks, dependencies)
    process.stdout.write(renderWaves(tasks, depths, timings))
  } else if (args.command === 'explain') {
    const depths = computeDepths(tasks, dependencies)
    const timings = computeTimings(tasks, dependencies)
    process.stdout.write(renderExplain(tasks, depths, timings))
  } else {
    const priorities = computePriorities(tasks, dependencies)
    process.stdout.write(renderPack(tasks, dependencies, priorities, args.workers))
  }
}

main().catch(err => {
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`)
  process.exitCode = 2
})

export { byName }
"}

{"file_path":"src/args.js","content":"const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

/**
 * Validate the command line. Returns `{ command, workers }` or `{ error }`.
 */
export function parseArgs(argv) {
  if (argv.length === 0) return { error: USAGE }

  const command = argv[0]

  if (command === 'waves' || command === 'explain') {
    if (argv.length !== 1) return { error: USAGE }
    return { command }
  }

  if (command === 'pack') {
    if (argv.length !== 2) return { error: USAGE }
    const workers = argv[1]
    if (!/^[1-9][0-9]*$/.test(workers)) {
      return { error: 'error: workers must be a positive integer' }
    }
    return { command, workers: Number(workers) }
  }

  return { error: USAGE }
}
"}

{"file_path":"src/parse.js","content":"const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Read the build graph text. Returns `{ tasks, dependencies }` or `{ error }`.
 *
 * `tasks` maps a name to `{ name, cost }`; `dependencies` maps a name to the
 * set of names it depends on.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const dependencies = new Map()
  const used = [] // every name a dep line mentions, in input order

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const n = i + 1
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        return { error: `error: line ${n}: expected task <name> <cost>` }
      }
      const name = words[1]
      const cost = words[2]
      if (!NAME.test(name)) {
        return { error: `error: line ${n}: invalid task name ${name}` }
      }
      if (!COST.test(cost)) {
        return { error: `error: line ${n}: cost must be a non-negative integer` }
      }
      if (tasks.has(name)) {
        return { error: `error: line ${n}: task ${name} is declared twice` }
      }
      tasks.set(name, { name, cost: Number(cost) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        return { error: `error: line ${n}: expected dep <name> <dependency>...` }
      }
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) {
          return { error: `error: line ${n}: invalid task name ${words[w]}` }
        }
        used.push(words[w])
      }
      const name = words[1]
      let set = dependencies.get(name)
      if (!set) {
        set = new Set()
        dependencies.set(name, set)
      }
      for (let w = 2; w < words.length; w++) set.add(words[w])
    } else {
      return { error: `error: line ${n}: unknown directive ${directive}` }
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) return { error: `error: unknown task ${name}` }
  }

  return { tasks, dependencies }
}
"}

{"file_path":"src/graph.js","content":"/** Ascending order on the raw characters of a name. */
export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

function depsOf(dependencies, name) {
  const set = dependencies.get(name)
  return set ? Array.from(set).sort(byName) : []
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Returns the names of the cycle, the first one repeated at the end, or
 * null when the graph is acyclic.
 */
export function findCycle(tasks, dependencies) {
  const done = new Set()
  const onStack = new Set()
  const roots = Array.from(tasks.keys()).sort(byName)

  for (const root of roots) {
    if (done.has(root)) continue

    // Iterative depth-first search so that deep graphs do not overflow.
    const path = [root]
    const cursor = [0]
    onStack.add(root)

    while (path.length > 0) {
      const node = path[path.length - 1]
      const deps = depsOf(dependencies, node)
      const i = cursor[cursor.length - 1]

      if (i < deps.length) {
        cursor[cursor.length - 1] = i + 1
        const dep = deps[i]
        if (onStack.has(dep)) {
          const cycle = path.slice(path.indexOf(dep))
          cycle.push(dep)
          return cycle
        }
        if (!done.has(dep)) {
          path.push(dep)
          cursor.push(0)
          onStack.add(dep)
        }
      } else {
        onStack.delete(node)
        done.add(node)
        path.pop()
        cursor.pop()
      }
    }
  }

  return null
}

/** A reverse topological order: every task comes after its dependencies. */
function topoOrder(tasks, dependencies) {
  const order = []
  const seen = new Set()

  for (const root of Array.from(tasks.keys()).sort(byName)) {
    if (seen.has(root)) continue
    const path = [root]
    const cursor = [0]
    seen.add(root)
    while (path.length > 0) {
      const node = path[path.length - 1]
      const deps = depsOf(dependencies, node)
      const i = cursor[cursor.length - 1]
      if (i < deps.length) {
        cursor[cursor.length - 1] = i + 1
        const dep = deps[i]
        if (!seen.has(dep)) {
          seen.add(dep)
          path.push(dep)
          cursor.push(0)
        }
      } else {
        order.push(node)
        path.pop()
        cursor.pop()
      }
    }
  }

  return order
}

/** The wave each task sits in: one more than its deepest dependency. */
export function computeDepths(tasks, dependencies) {
  const depth = new Map()
  for (const name of topoOrder(tasks, dependencies)) {
    let max = -1
    for (const dep of depsOf(dependencies, name)) {
      max = Math.max(max, depth.get(dep))
    }
    depth.set(name, max + 1)
  }
  return depth
}

/** The start and finish of every task with unlimited workers. */
export function computeTimings(tasks, dependencies) {
  const timings = new Map()
  for (const name of topoOrder(tasks, dependencies)) {
    let start = 0
    for (const dep of depsOf(dependencies, name)) {
      start = Math.max(start, timings.get(dep).finish)
    }
    timings.set(name, { start, finish: start + tasks.get(name).cost })
  }
  return timings
}

/** The cost of the longest chain that begins at each task. */
export function computePriorities(tasks, dependencies) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of dependencies) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  // Dependencies come first in the topological order, so walk it backwards:
  // every dependent of a task is settled before the task itself.
  const order = topoOrder(tasks, dependencies)
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let tail = 0
    for (const other of dependents.get(name)) {
      tail = Math.max(tail, priority.get(other))
    }
    priority.set(name, tasks.get(name).cost + tail)
  }
  return priority
}
"}

{"file_path":"src/render.js","content":"import { byName } from './graph.js'

function total(timings) {
  let t = 0
  for (const timing of timings.values()) t = Math.max(t, timing.finish)
  return t
}

export function renderWaves(tasks, depths, timings) {
  const waves = []
  for (const [name, d] of depths) {
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }

  let out = ''
  for (let w = 0; w < waves.length; w++) {
    const names = (waves[w] || []).sort(byName)
    out += `wave ${w}: ${names.join(' ')}\n`
  }
  return out + `total ${total(timings)}\n`
}

export function renderExplain(tasks, depths, timings) {
  let out = ''
  for (const name of Array.from(tasks.keys()).sort(byName)) {
    const { start, finish } = timings.get(name)
    out += `${name} start=${start} finish=${finish} depth=${depths.get(name)}\n`
  }
  return out + `total ${total(timings)}\n`
}

/**
 * List scheduling: at each instant, fill every free worker with the ready task
 * of greatest priority, ties broken by ascending name.
 */
export function renderPack(tasks, dependencies, priorities, workerCount) {
  const workers = []
  for (let i = 0; i < workerCount; i++) workers.push({ free: 0, runs: [] })

  const finish = new Map() // name -> finish, once started
  const pending = new Set(tasks.keys())
  let time = 0

  while (pending.size > 0) {
    for (;;) {
      const worker = workers.find(w => w.free <= time)
      if (!worker) break

      let best = null
      for (const name of pending) {
        let ready = true
        for (const dep of dependencies.get(name) || []) {
          if (!finish.has(dep) || finish.get(dep) > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && byName(name, best) < 0)
        ) {
          best = name
        }
      }
      if (best === null) break

      const end = time + tasks.get(best).cost
      worker.runs.push(`${best}@${time}-${end}`)
      worker.free = end
      finish.set(best, end)
      pending.delete(best)
    }

    if (pending.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.free > time) next = Math.min(next, worker.free)
    }
    if (next === Infinity) break // nothing can ever start
    time = next
  }

  let out = ''
  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const runs = workers[i].runs
    out += `worker ${i}:` + runs.map(r => ' ' + r).join('') + '\n'
  }
  for (const end of finish.values()) makespan = Math.max(makespan, end)
  return out + `makespan ${makespan}\n`
}
"}

