{"file_path":"src/scanner.js","content":"/**
 * A scanner that tokenizes source code according to the language specification.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null']);

export class Scanner {
  constructor(input) {
    this.input = input;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.error = null;
  }

  peek(offset = 0) {
    const idx = this.pos + offset;
    return idx < this.input.length ? this.input[idx] : null;
  }

  advance() {
    if (this.pos >= this.input.length) return null;

    const char = this.input[this.pos++];

    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else if (char === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1) / 4 + 1) * 4 + 1;
    } else {
      this.column++;
    }

    return char;
  }

  skipWhitespace() {
    while (this.peek() && /[ \t\r]/.test(this.peek())) {
      this.advance();
    }
  }

  scanLineComment() {
    // We're at the first '/', peek for second '/'
    if (this.peek() === '/' && this.peek(1) === '/') {
      this.advance(); // consume first /
      this.advance(); // consume second /

      // Skip until newline or end
      while (this.peek() && this.peek() !== '\n') {
        this.advance();
      }
      return true;
    }
    return false;
  }

  scanBlockComment() {
    // We're at the first '/', peek for '*'
    if (this.peek() === '/' && this.peek(1) === '*') {
      const startLine = this.line;
      const startCol = this.column;

      this.advance(); // consume /
      this.advance(); // consume *

      let nesting = 1;
      while (nesting > 0 && this.peek()) {
        if (this.peek() === '/' && this.peek(1) === '*') {
          this.advance();
          this.advance();
          nesting++;
        } else if (this.peek() === '*' && this.peek(1) === '/') {
          this.advance();
          this.advance();
          nesting--;
        } else {
          this.advance();
        }
      }

      if (nesting > 0) {
        this.error = { line: startLine, column: startCol, message: 'unterminated block comment' };
        return false;
      }
      return true;
    }
    return false;
  }

  isIdentifierStart(char) {
    if (!char) return false;
    return /[a-zA-Z_]/.test(char);
  }

  isIdentifierContinue(char) {
    if (!char) return false;
    return /[a-zA-Z0-9_]/.test(char);
  }

  isDigit(char) {
    if (!char) return false;
    return /[0-9]/.test(char);
  }

  isHexDigit(char) {
    if (!char) return false;
    return /[0-9a-fA-F]/.test(char);
  }

  isBinaryDigit(char) {
    if (!char) return false;
    return /[01]/.test(char);
  }

  isOctalDigit(char) {
    if (!char) return false;
    return /[0-7]/.test(char);
  }

  scanIdentifier() {
    if (!this.isIdentifierStart(this.peek())) return null;

    const startLine = this.line;
    const startCol = this.column;
    let text = '';

    while (this.isIdentifierContinue(this.peek())) {
      text += this.advance();
    }

    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident';
    return { kind, text, line: startLine, column: startCol };
  }

  scanNumber() {
    if (!this.isDigit(this.peek())) return null;

    const startLine = this.line;
    const startCol = this.column;
    let text = '';

    // Check for hex, binary, octal
    if (this.peek() === '0') {
      text += this.advance();

      const prefix = this.peek();
      if (prefix === 'x' || prefix === 'X') {
        text += this.advance();

        if (!this.isHexDigit(this.peek())) {
          // Invalid: 0x with no digit after
          while (this.isIdentifierContinue(this.peek())) {
            text += this.advance();
          }
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        while (this.isHexDigit(this.peek()) || this.peek() === '_') {
          if (this.peek() === '_') {
            // Check if it's between two hex digits
            const nextChar = this.peek(1);
            if (!this.isHexDigit(nextChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
            const prevChar = text[text.length - 1];
            if (!this.isHexDigit(prevChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
          }
          text += this.advance();
        }

        // Check for invalid trailing characters
        if (this.isIdentifierContinue(this.peek())) {
          text += this.advance();
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        return { kind: 'number', text, line: startLine, column: startCol };
      } else if (prefix === 'b' || prefix === 'B') {
        text += this.advance();

        if (!this.isBinaryDigit(this.peek())) {
          while (this.isIdentifierContinue(this.peek())) {
            text += this.advance();
          }
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        while (this.isBinaryDigit(this.peek()) || this.peek() === '_') {
          if (this.peek() === '_') {
            const nextChar = this.peek(1);
            if (!this.isBinaryDigit(nextChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
            const prevChar = text[text.length - 1];
            if (!this.isBinaryDigit(prevChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
          }
          text += this.advance();
        }

        if (this.isIdentifierContinue(this.peek())) {
          text += this.advance();
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        return { kind: 'number', text, line: startLine, column: startCol };
      } else if (prefix === 'o' || prefix === 'O') {
        text += this.advance();

        if (!this.isOctalDigit(this.peek())) {
          while (this.isIdentifierContinue(this.peek())) {
            text += this.advance();
          }
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        while (this.isOctalDigit(this.peek()) || this.peek() === '_') {
          if (this.peek() === '_') {
            const nextChar = this.peek(1);
            if (!this.isOctalDigit(nextChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
            const prevChar = text[text.length - 1];
            if (!this.isOctalDigit(prevChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
          }
          text += this.advance();
        }

        if (this.isIdentifierContinue(this.peek())) {
          text += this.advance();
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }

        return { kind: 'number', text, line: startLine, column: startCol };
      }
    }

    // Decimal number
    while (this.isDigit(this.peek()) || this.peek() === '_') {
      if (this.peek() === '_') {
        const nextChar = this.peek(1);
        if (!this.isDigit(nextChar)) {
          text += this.advance();
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }
        const prevChar = text[text.length - 1];
        if (!this.isDigit(prevChar)) {
          text += this.advance();
          this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
          return null;
        }
      }
      text += this.advance();
    }

    // Optional decimal point
    if (this.peek() === '.') {
      const nextChar = this.peek(1);
      if (this.isDigit(nextChar)) {
        text += this.advance(); // consume .
        while (this.isDigit(this.peek()) || this.peek() === '_') {
          if (this.peek() === '_') {
            const nextChar = this.peek(1);
            if (!this.isDigit(nextChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
            const prevChar = text[text.length - 1];
            if (!this.isDigit(prevChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
          }
          text += this.advance();
        }
      }
    }

    // Optional exponent
    if (this.peek() === 'e' || this.peek() === 'E') {
      const expChar = this.peek(1);
      const isSign = expChar === '+' || expChar === '-';
      const digitAfter = isSign ? this.peek(2) : expChar;

      if (this.isDigit(digitAfter)) {
        text += this.advance(); // consume e/E
        if (isSign) {
          text += this.advance(); // consume +/-
        }
        while (this.isDigit(this.peek()) || this.peek() === '_') {
          if (this.peek() === '_') {
            const nextChar = this.peek(1);
            if (!this.isDigit(nextChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
            const prevChar = text[text.length - 1];
            if (!this.isDigit(prevChar)) {
              text += this.advance();
              this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
              return null;
            }
          }
          text += this.advance();
        }
      }
    }

    // Check for invalid trailing characters
    if (this.isIdentifierContinue(this.peek())) {
      text += this.advance();
      this.error = { line: startLine, column: startCol, message: `invalid number ${text}` };
      return null;
    }

    return { kind: 'number', text, line: startLine, column: startCol };
  }

  scanString() {
    if (this.peek() !== '"') return null;

    const startLine = this.line;
    const startCol = this.column;
    this.advance(); // consume opening "

    let value = '';

    while (this.peek() && this.peek() !== '"') {
      if (this.peek() === '\n') {
        this.error = { line: this.line, column: this.column, message: 'newline in string' };
        return null;
      }

      if (this.peek() === '\\') {
        const backslashLine = this.line;
        const backslashCol = this.column;
        this.advance(); // consume backslash

        const escaped = this.peek();

        switch (escaped) {
          case 'n':
            this.advance();
            value += '\n';
            break;
          case 't':
            this.advance();
            value += '\t';
            break;
          case 'r':
            this.advance();
            value += '\r';
            break;
          case '\\':
            this.advance();
            value += '\\';
            break;
          case '"':
            this.advance();
            value += '"';
            break;
          case '0':
            this.advance();
            value += '\0';
            break;
          case 'x': {
            this.advance();
            const h1 = this.peek();
            const h2 = this.peek(1);

            if (!this.isHexDigit(h1) || !this.isHexDigit(h2)) {
              this.error = { line: backslashLine, column: backslashCol, message: `invalid escape \\${escaped}` };
              return null;
            }

            this.advance();
            this.advance();
            const code = parseInt(h1 + h2, 16);
            value += String.fromCharCode(code);
            break;
          }
          case 'u': {
            this.advance();
            if (this.peek() !== '{') {
              this.error = { line: backslashLine, column: backslashCol, message: `invalid escape \\${escaped}` };
              return null;
            }

            this.advance(); // consume {

            let hexStr = '';
            while (this.peek() && this.peek() !== '}') {
              if (!this.isHexDigit(this.peek())) {
                this.error = { line: backslashLine, column: backslashCol, message: `invalid escape \\u` };
                return null;
              }
              hexStr += this.advance();
            }

            if (!this.peek()) {
