 */
function suffixLcsTable(base, doc) {
  const n = base.length
  const m = doc.length
  const width = m + 1
  const table = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    const row = i * width
    const next = (i + 1) * width
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === doc[j]) {
        table[row + j] = table[next + j + 1] + 1
      } else {
        const skipBase = table[next + j]
        const skipDoc = table[row + j + 1]
        table[row + j] = skipBase >= skipDoc ? skipBase : skipDoc
      }
    }
  }
  return table
