 * The matching pairs of a longest common subsequence of `base` and `doc`,
 * choosing among the equally long ones the one whose matches come earliest.
 * Each pair is `[baseIndex, docIndex]`.
 */
export function longestCommonSubsequence(base, doc) {
  const n = base.length
  const m = doc.length
  const width = m + 1
  const table = suffixLcsTable(base, doc)
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === doc[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (table[(i + 1) * width + j] >= table[i * width + j + 1]) {
      i++
    } else {
      j++
    }
  }
